import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>

#define K 3
#define TILE 16
#define TILE_H (TILE + K - 1)
__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    int tiles_w)
{
    extern __shared__ float s_mem[];
    float* s_weight = s_mem;                       // size = C_in*K*K
    float* s_input  = s_mem + C_in * K * K;         // size = C_in*TILE_H*TILE_H
    int n  = blockIdx.x;
    int oc = blockIdx.y;
    int tile_idx = blockIdx.z;
    int tile_row = tile_idx / tiles_w;
    int tile_col = tile_idx % tiles_w;
    int oh_base = tile_row * TILE;
    int ow_base = tile_col * TILE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    int nthreads = blockDim.x * blockDim.y;
    int wsize = C_in * K * K;
    for (int i = tid; i < wsize; i += nthreads) {
        s_weight[i] = __bfloat162float(weight[oc * wsize + i]);
    }
    const __nv_bfloat16* input_n = input + (size_t)n * C_in * H * W;
    int input_tile_size = TILE_H * TILE_H;
    int total_input_elems = C_in * input_tile_size;
    for (int i = tid; i < total_input_elems; i += nthreads) {
        int c = i / input_tile_size;
        int rem = i % input_tile_size;
        int row = rem / TILE_H;
        int col = rem % TILE_H;
        int ih = oh_base + row;
        int iw = ow_base + col;
        float val = 0.0f;
        if (ih < H && iw < W) {
            val = __bfloat162float(input_n[(size_t)c * H * W + (size_t)ih * W + iw]);
        }
        s_input[i] = val;
    }
    __syncthreads();
    int oh = oh_base + ty;
    int ow = ow_base + tx;
    if (oh >= H_out || ow >= W_out) return;
    float sum = 0.0f;
    for (int c = 0; c < C_in; c++) {
        const float* in_c = s_input + c * input_tile_size;
        const float* wgt_c = s_weight + c * K * K;
        #pragma unroll
        for (int kh = 0; kh < K; kh++) {
            #pragma unroll
            for (int kw = 0; kw < K; kw++) {
                float val = in_c[(ty + kh) * TILE_H + (tx + kw)];
                sum += val * wgt_c[kh * K + kw];
            }
        }
    }
    size_t out_idx = ((size_t)n * C_out + oc) * H_out * W_out + (size_t)oh * W_out + ow;
    output[out_idx] = __float2bfloat16(sum);
}
torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bf16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bf16");
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int kernel_size = weight.size(2); // assume square, = K
    int H_out = H - kernel_size + 1;
    int W_out = W - kernel_size + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    dim3 block(TILE, TILE);
    int tiles_h = (H_out + TILE - 1) / TILE;
    int tiles_w = (W_out + TILE - 1) / TILE;
    dim3 grid(N, C_out, tiles_h * tiles_w);
    size_t shmem_size = (size_t)(C_in * K * K + C_in * TILE_H * TILE_H) * sizeof(float);
    conv2d_bf16_kernel<<<grid, block, shmem_size>>>(
        reinterpret_cast<const __nv_bfloat16*>(input.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        N, C_in, H, W, C_out, H_out, W_out, tiles_w
    );
    return output;
}
